def match_parens(lst):
    def is_good(s):
        balance = 0
        for char in s:
            if char == '(':
                balance += 1
            else:
                balance -= 1
            if balance < 0:
                return False
        return balance == 0

    # Try concatenating the two strings in both possible orders
    order1 = lst[0] + lst[1]
    order2 = lst[1] + lst[0]

    if is_good(order1) or is_good(order2):
        return 'Yes'
    else:
        return 'No'
